<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
const props = defineProps<{ wedding: { id: number; name: string; logistics: { id: number; type: string; name: string; status: string; contact: string | null; notes: string | null }[]; inspirations: { id: number; title: string; category: string; note: string | null; reference_url: string | null }[] }; canEdit: boolean }>();
const logistic = useForm({ type: 'vendor', name: '', status: 'recommended', contact: '', notes: '' }); const inspiration = useForm({ title: '', category: 'general', note: '', reference_url: '' });
function addLogistic(): void { logistic.post(route('weddings.planning.logistics.store', props.wedding.id), { preserveScroll: true, onSuccess: () => logistic.reset() }); } function addInspiration(): void { inspiration.post(route('weddings.planning.inspirations.store', props.wedding.id), { preserveScroll: true, onSuccess: () => inspiration.reset() }); }
</script>
<template><Head :title="`Logística · ${wedding.name}`"/><AuthenticatedLayout><template #header><div><Link :href="route('weddings.planning.index', wedding.id)" class="text-sm text-rose-800 underline">← Planeación</Link><h1 class="mt-1 font-serif text-3xl">Logística e inspiración</h1></div></template><div class="mx-auto grid max-w-5xl gap-6 px-4 py-8 md:grid-cols-2"><section class="rounded-2xl border bg-white p-5"><h2 class="font-serif text-xl">Recursos</h2><article v-for="item in wedding.logistics" :key="item.id" class="mt-3 border-t pt-3 text-sm"><b>{{ item.name }}</b> · {{ item.type }} · {{ item.status }}<p v-if="item.contact">{{ item.contact }}</p><p v-if="item.notes">{{ item.notes }}</p></article><form v-if="canEdit" class="mt-5 space-y-2" @submit.prevent="addLogistic"><select v-model="logistic.type" class="w-full rounded border-stone-300"><option value="vendor">Proveedor</option><option value="hotel">Hotel</option><option value="transport">Transporte</option><option value="venue">Recinto</option><option value="decor">Decoración</option><option value="cake">Pastel</option></select><input v-model="logistic.name" required class="w-full rounded border-stone-300" placeholder="Nombre"><select v-model="logistic.status" class="w-full rounded border-stone-300"><option value="recommended">Recomendado</option><option value="managed">Gestionado</option><option value="reserved">Reservado</option><option value="confirmed">Confirmado</option></select><input v-model="logistic.contact" class="w-full rounded border-stone-300" placeholder="Contacto"><textarea v-model="logistic.notes" class="w-full rounded border-stone-300" placeholder="Notas"/><button class="rounded bg-rose-800 px-3 py-2 text-sm text-white">Agregar recurso</button></form></section><section class="rounded-2xl border bg-white p-5"><h2 class="font-serif text-xl">Inspiración</h2><article v-for="item in wedding.inspirations" :key="item.id" class="mt-3 border-t pt-3 text-sm"><b>{{ item.title }}</b> · {{ item.category }}<p v-if="item.note">{{ item.note }}</p><a v-if="item.reference_url" :href="item.reference_url" target="_blank" rel="noopener" class="text-rose-800 underline">Abrir referencia</a></article><form v-if="canEdit" class="mt-5 space-y-2" @submit.prevent="addInspiration"><input v-model="inspiration.title" required class="w-full rounded border-stone-300" placeholder="Idea o referencia"><input v-model="inspiration.category" required class="w-full rounded border-stone-300" placeholder="Categoría"><textarea v-model="inspiration.note" class="w-full rounded border-stone-300" placeholder="Nota"/><input v-model="inspiration.reference_url" type="url" class="w-full rounded border-stone-300" placeholder="URL opcional"><button class="rounded bg-rose-800 px-3 py-2 text-sm text-white">Agregar inspiración</button></form></section></div></AuthenticatedLayout></template>
